import json
from pathlib import Path
import textwrap

ROOT = Path(__file__).resolve().parents[1]
LESSONS = []


def lesson(key, article, title, goal, concepts, explanation, walkthrough, mistake, exercise, code, cases, dependencies=(), source='https://docs.python.org/3/tutorial/'):
    LESSONS.append(dict(key='py-'+key, slug='python-basics-'+key, article=article, title=title, goal=goal, concepts=concepts, explanation=explanation, walkthrough=walkthrough, mistake=mistake, exercise=exercise, code=textwrap.dedent(code).strip(), cases=cases, dependencies=list(dependencies), source=source))


lesson('hello', 'نصب و اجرای پایتون؛ اولین برنامه از صفر', 'کارت خوشامدگویی شخصی',
       'اجرای اولین تابع و ساخت رشته با نام ورودی', 'print · str · f-string',
       'پایتون مفسر است؛ فایل متنی با پسوند py را به مفسر می‌دهیم تا دستورها اجرا شوند. برای شروع نیازی به یادگیری ماشین یا نصب بسته‌های علمی ندارید. در رایانهٔ شخصی Python 3 را نصب کنید و با python --version نسخه را ببینید؛ در بعضی سیستم‌ها نام فرمان python3 است. در میزکار سایت، مفسر از قبل آماده است. نام فایل را hello.py بگذارید و از نام‌هایی مثل json.py پرهیز کنید، چون ممکن است ماژول استاندارد را بپوشاند.',
       'تابع solve یک دیکشنری می‌گیرد و یک دیکشنری برمی‌گرداند. کلید name نام شخص است. strip فاصله‌های ابتدا و انتهای نام را برمی‌دارد، اما فاصلهٔ بین اجزای نام را حفظ می‌کند. اگر نتیجه خالی باشد، نام عمومی «دوست» را انتخاب می‌کنیم. f-string مقدار متغیر را داخل آکولاد قرار می‌دهد. خروجی این مثال «سلام، سارا!» است؛ ویرگول فارسی و علامت تعجب هم جزئی از متن مورد انتظارند.',
       'print برای دیدن خروجی است، ولی return نتیجه را به فراخواننده می‌دهد. چاپ متن بدون برگرداندن دیکشنری، قرارداد پروژه را برآورده نمی‌کند. تورفتگی چهار فاصلهٔ یکسان داشته باشید؛ مخلوط‌کردن تب و فاصله ممکن است IndentationError بدهد.',
       'نام را به «علی رضا» تغییر دهید؛ سپس رشتهٔ خالی و نامی با فاصلهٔ دو طرف را امتحان کنید و قبل از اجرا خروجی هر کدام را بنویسید.',
       '''
       def solve(data):
           name = data['name'].strip() or 'دوست'
           return {'message': f'سلام، {name}!'}
       ''', [({'name':'سارا'}, {'message':'سلام، سارا!'}), ({'name':'  علی رضا  '}, {'message':'سلام، علی رضا!'}), ({'name':''}, {'message':'سلام، دوست!'})])

lesson('receipt', 'متغیر و عملگر در پایتون؛ محاسبهٔ یک رسید', 'محاسبه‌گر مبلغ خرید',
       'استفاده از متغیر، ضرب و گردکردن خروجی عددی', 'Variables · float · round',
       'متغیر نامی برای یک مقدار است، نه خانه‌ای که همیشه یک نوع ثابت دارد. نام‌هایی مثل price و quantity بهتر از a و b منظور محاسبه را نشان می‌دهند. عدد صحیح برای تعداد و عدد اعشاری برای قیمت مناسب است. علامت = مقداردهی می‌کند و با == که مقایسه است فرق دارد. در پایتون ضرب با * نوشته می‌شود؛ نوشتن دو نام کنار هم ضرب محسوب نمی‌شود.',
       'قیمت واحد را در تعداد ضرب می‌کنیم و مبلغ نهایی را تا دو رقم اعشار گرد می‌کنیم. برای قیمت ۱۲٫۵ و تعداد ۳، نتیجه ۳۷٫۵ است. quantity برابر صفر باید مبلغ صفر بسازد، نه خطا. ورودی این تمرین عدد JSON است، نه رشته؛ بنابراین تبدیل با float لازم نیست. تفاوت رشتهٔ "12" با عدد 12 را با type در یک برنامهٔ جدا ببینید.',
       'float نمایش دقیق همهٔ اعشار ده‌دهی نیست؛ مثلاً 0.1 + 0.2 ممکن است نمایش طولانی داشته باشد. round برای این تمرین کافی است، ولی برای حسابداری دقیق بعداً Decimal را یاد می‌گیریم. هیچ‌وقت برای جمع عددها آن‌ها را به رشته تبدیل نکنید.',
       'قیمت را ۰٫۱ و تعداد را ۳ بگذارید. نمایش ضرب خام و خروجی round را مقایسه کنید. سپس نام متغیرها را بدون تغییر رفتار برنامه خواناتر کنید.',
       '''
       def solve(data):
           total = data['price'] * data['quantity']
           return {'total': round(total, 2)}
       ''', [({'price':12.5,'quantity':3},{'total':37.5}), ({'price':99,'quantity':0},{'total':0}), ({'price':0.1,'quantity':3},{'total':0.3})])

lesson('temperature', 'نوع داده و تبدیل واحد؛ از رشته تا عدد', 'مبدل دمای سانتی‌گراد و فارنهایت',
       'شناخت ورودی عددی و انتخاب فرمول با یک شرط', 'Types · Arithmetic · Branching',
       'نوع مقدار تعیین می‌کند چه عملی روی آن معنی دارد. جمع دو رشته آن‌ها را به هم می‌چسباند، ولی جمع دو عدد محاسبه می‌کند. داده‌ای که از input می‌آید رشته است؛ اگر قرار است عدد باشد باید آن را با float تبدیل کنید. در این پروژه ورودی JSON از قبل عدد دارد و استفاده از input لازم نیست. کلید unit واحد ورودی را با C یا F مشخص می‌کند.',
       'برای تبدیل سانتی‌گراد به فارنهایت، عدد را در ۹ تقسیم بر ۵ ضرب و ۳۲ اضافه می‌کنیم. جهت عکس ابتدا ۳۲ را کم می‌کند و سپس در ۵ تقسیم بر ۹ ضرب می‌کند. شرط if شاخهٔ مناسب را انتخاب می‌کند. در خروجی علاوه بر مقدار، واحد جدید را می‌نویسیم تا عدد بدون معنا باقی نماند. دمای منفی هم ورودی معتبر است.',
       'ترتیب پرانتز در فرمول جهت عکس مهم است: (value - 32) * 5 / 9 با value - 32 * 5 / 9 برابر نیست. اگر واحد ناشناخته باشد، خروجی error=invalid_unit می‌دهیم؛ حدس‌زدن واحد اشتباه نتیجه‌ای ظاهراً معتبر تولید می‌کند.',
       'صفر و صد سانتی‌گراد را تبدیل کنید. سپس نتیجه را در جهت عکس تبدیل کنید و ببینید تا دقت دو رقم به ورودی اولیه نزدیک می‌شوید یا نه.',
       '''
       def solve(data):
           value, unit = data['value'], data['unit']
           if unit == 'C':
               return {'value': round(value * 9 / 5 + 32, 2), 'unit': 'F'}
           if unit == 'F':
               return {'value': round((value - 32) * 5 / 9, 2), 'unit': 'C'}
           return {'error': 'invalid_unit'}
       ''', [({'value':0,'unit':'C'},{'value':32,'unit':'F'}), ({'value':212,'unit':'F'},{'value':100,'unit':'C'}), ({'value':-40,'unit':'C'},{'value':-40,'unit':'F'}), ({'value':5,'unit':'K'},{'error':'invalid_unit'})])

lesson('conditions', 'شرط‌ها در پایتون؛ if و مرزهای تصمیم', 'تشخیص قبولی نمره',
       'نوشتن شرط با بازهٔ معتبر و آزمودن مرز قبولی', 'if · elif · Comparisons',
       'شرط یک عبارت با نتیجهٔ درست یا نادرست است. if فقط وقتی بدنه را اجرا می‌کند که شرط برقرار باشد. در مسئلهٔ قبولی، ابتدا باید معلوم کنیم نمره معتبر است یا نه؛ نمرهٔ بیشتر از بیست نباید صرفاً چون از ده بزرگ‌تر است پذیرفته شود. اعتبارسنجی مرز ورودی را از منطق تصمیم جدا کنید تا خواندن برنامه آسان بماند.',
       'دامنهٔ نمره صفر تا بیست، شامل هر دو سر بازه است. بعد از بررسی این دامنه، نمرهٔ حداقل ده پذیرفته می‌شود. نوشتن 0 <= score <= 20 یک مقایسهٔ زنجیره‌ای خواناست. خروجی passed یک مقدار بولی واقعی است؛ True و False در پایتون با حرف بزرگ شروع می‌شوند و در JSON به true و false تبدیل می‌شوند.',
       'علامت > با >= فرق دارد؛ اگر شرط score > 10 باشد، نمرهٔ دقیق ده اشتباه رد می‌شود. عبارت "False" رشته‌ای غیرخالی است و در شرط درست محسوب می‌شود. به جای رشته، مقدار بولی برگردانید.',
       'برای نمره‌های ۰، ۹٫۹۹، ۱۰، ۲۰ و ۲۰٫۰۱ جدول خروجی بسازید. توضیح دهید چرا بررسی بازه باید پیش از تشخیص قبولی انجام شود.',
       '''
       def solve(data):
           score = data['score']
           if not 0 <= score <= 20:
               return {'error': 'invalid_score'}
           return {'passed': score >= 10}
       ''', [({'score':10},{'passed':True}), ({'score':9.99},{'passed':False}), ({'score':20},{'passed':True}), ({'score':-1},{'error':'invalid_score'}), ({'score':21},{'error':'invalid_score'})])

lesson('loops', 'حلقهٔ for و باقیمانده؛ پردازش چند عدد', 'جداسازی و جمع اعداد زوج',
       'پیمایش لیست و ساخت خروجی بدون تغییر ورودی', 'for · modulo · append',
       'وقتی یک کار برای چند مقدار تکرار می‌شود، حلقه جای تکرار دستی دستورها را می‌گیرد. for هر عضو لیست را به ترتیب در اختیار بدنه قرار می‌دهد. برای تشخیص زوج‌بودن، باقیماندهٔ تقسیم بر دو را با صفر مقایسه می‌کنیم. صفر و اعداد منفی زوج هم این شرط را دارند؛ مثبت‌بودن بخشی از تعریف زوج نیست.',
       'ابتدا لیست خالی evens می‌سازیم. در هر دور، اگر عدد زوج باشد آن را با append به انتهای لیست می‌افزاییم. در پایان sum جمع همین لیست را حساب می‌کند. ترتیب و تکرار عددها باید حفظ شود؛ اگر ۲ دوبار در ورودی باشد، در خروجی هم دو بار می‌آید. ورودی خالی به لیست خالی و جمع صفر منجر می‌شود.',
       'حذف عضو از همان لیستی که روی آن حلقه می‌زنید ممکن است باعث ردشدن بعضی عضوها شود. خروجی جدا بسازید. return نباید داخل حلقه باشد، چون برنامه پس از اولین عدد تمام می‌شود. برای مقایسه از == و نه = استفاده کنید.',
       'ورودی [۲، ۲، ۳، منفی۴، ۰] را دستی دنبال کنید و مقدار evens را بعد از هر دور بنویسید. سپس نسخه‌ای برای جداکردن اعداد فرد بسازید.',
       '''
       def solve(data):
           evens = []
           for number in data['numbers']:
               if number % 2 == 0:
                   evens.append(number)
           return {'evens': evens, 'total': sum(evens)}
       ''', [({'numbers':[1,2,3,4]},{'evens':[2,4],'total':6}), ({'numbers':[-4,0,2,2]},{'evens':[-4,0,2,2],'total':0}), ({'numbers':[]},{'evens':[],'total':0})])

lesson('lists', 'لیست در پایتون؛ طول، کمینه، بیشینه و میانگین', 'خلاصه‌ساز فهرست اندازه‌گیری‌ها',
       'استفاده از توابع داخلی با مدیریت لیست خالی', 'list · len · min · max · sum',
       'لیست مجموعه‌ای مرتب از مقدارهاست و با براکت نوشته می‌شود. برای خواندن عضو اول از اندیس صفر استفاده می‌کنیم. طول لیست با len به دست می‌آید و با آخرین اندیس یکی نیست. در این تمرین به جای نوشتن الگوریتم مرتب‌سازی، از توابع داخلی min و max استفاده می‌کنیم؛ هدف شناخت ابزار مناسب و قرارداد خروجی است.',
       'میانگین برابر جمع عددها تقسیم بر تعداد آن‌هاست. پیش از این تقسیم، خالی‌بودن لیست را بررسی می‌کنیم. برای دادهٔ خالی، count صفر و سه شاخص دیگر None هستند؛ این مقدار در JSON به null تبدیل می‌شود. صفر جایگزین مناسبی برای میانگین ناموجود نیست، چون ممکن است واقعاً میانگین اندازه‌گیری‌ها صفر باشد.',
       'اجرای min روی لیست خالی ValueError می‌دهد و تقسیم بر طول صفر ZeroDivisionError می‌سازد. بررسی if not values هر دو مشکل را قبل از محاسبه حل می‌کند. تابع sort لیست را درجا تغییر می‌دهد و None برمی‌گرداند؛ برای این پروژه اصلاً به آن نیاز نداریم.',
       'ورودی تک‌عضوی را بررسی کنید؛ هر سه شاخص باید همان عدد باشند. سپس دو عدد با علامت مخالف وارد کنید تا تفاوت میانگین صفر و میانگین ناموجود روشن شود.',
       '''
       def solve(data):
           values = data['values']
           if not values:
               return {'count': 0, 'min': None, 'max': None, 'mean': None}
           return {'count': len(values), 'min': min(values), 'max': max(values), 'mean': sum(values) / len(values)}
       ''', [({'values':[2,4,9]},{'count':3,'min':2,'max':9,'mean':5}), ({'values':[]},{'count':0,'min':None,'max':None,'mean':None}), ({'values':[-3]},{'count':1,'min':-3,'max':-3,'mean':-3})])

lesson('strings', 'رشته‌ها و متن فارسی؛ شمارش واژه با split', 'شمارندهٔ واژه‌های متن',
       'تبدیل متن به واژه و ساخت فراوانی با دیکشنری', 'str · split · casefold · dict',
       'رشته در پایتون دنباله‌ای از نویسه‌های یونیکد است، پس متن فارسی هم مانند انگلیسی قابل پردازش است. split بدون آرگومان، متن را بر اساس فاصله‌های سفید جدا می‌کند و فاصله‌های تکراری، تب و خط جدید را درست مدیریت می‌کند. تعریف واژه در این پروژه ساده است: هر بخش جداشده با فاصله یک واژه است، نه یک تحلیل زبانی کامل.',
       'ابتدا متن را با casefold برای مقایسهٔ بدون حساسیت به بزرگی حرف آماده می‌کنیم. سپس برای هر واژه شمارندهٔ دیکشنری را یکی افزایش می‌دهیم. get برای کلیدی که هنوز دیده نشده مقدار صفر می‌دهد. خروجی total تعداد کل واژه‌ها و counts فراوانی هر واژه است. در نمونهٔ انگلیسی Python و python یک کلید مشترک می‌سازند.',
       'نشانه‌گذاری حذف نمی‌شود؛ در این قرارداد «سلام» و «سلام!» دو واژهٔ متفاوت‌اند. همچنین ی فارسی و ي عربی خودبه‌خود یکی نمی‌شوند. اگر عادی‌سازی لازم دارید باید آن را صریح تعریف کنید، نه اینکه بی‌خبر بخشی از داده را تغییر دهید.',
       'متنی با چند خط، فاصلهٔ تکراری و واژهٔ فارسی تکرارشونده بسازید. تفاوت split() و split(" ") را مشاهده کنید و ببینید کدام‌یک عضو خالی تولید می‌کند.',
       '''
       def solve(data):
           words = data['text'].casefold().split()
           counts = {}
           for word in words:
               counts[word] = counts.get(word, 0) + 1
           return {'total': len(words), 'counts': counts}
       ''', [({'text':'Python python سلام'},{'total':3,'counts':{'python':2,'سلام':1}}), ({'text':' \n\t '},{'total':0,'counts':{}}), ({'text':'سلام  دنیا\nسلام'},{'total':3,'counts':{'سلام':2,'دنیا':1}})])

lesson('search', 'فیلترکردن لیست؛ جست‌وجوی متنی قابل پیش‌بینی', 'جست‌وجو در عنوان کتاب‌ها',
       'ترکیب شرط و پیمایش برای جست‌وجوی بدون حساسیت به حروف', 'Filtering · in · casefold',
       'جست‌وجوی ساده یعنی نگه‌داشتن عضوهایی که یک شرط دارند. عملگر in روی رشته بررسی می‌کند آیا یک زیررشته داخل آن وجود دارد یا نه. این با جست‌وجوی واژهٔ کامل فرق دارد؛ جست‌وجوی «data» می‌تواند داخل «database» هم نتیجه بدهد. پیش از نوشتن کد، همین تعریف را برای کاربر روشن کنید.',
       'عبارت جست‌وجو را strip و casefold می‌کنیم. هر عنوان را فقط برای مقایسه casefold می‌کنیم، اما خود عنوان اصلی را در خروجی نگه می‌داریم. بنابراین ظاهر حروف از بین نمی‌رود. اگر عبارت خالی باشد، لیست خالی برمی‌گردانیم تا معنی مشخصی داشته باشد. ترتیب نتیجه‌ها همان ترتیب کتاب‌های ورودی است و مرتب‌سازی جدیدی انجام نمی‌شود.',
       'رشتهٔ خالی داخل هر رشته وجود دارد؛ بدون بررسی query، جست‌وجوی خالی همهٔ کتاب‌ها را برمی‌گرداند. تغییر عنوان اصلی به حروف کوچک هم اشتباه است، چون نمایش را بی‌دلیل عوض می‌کند. این جست‌وجو به اینترنت و کتابخانهٔ خارجی نیاز ندارد.',
       'عبارت PYTHON را در دو عنوان با حروف مختلف جست‌وجو کنید. سپس عبارت ناموجود، عبارت خالی و لیست بدون کتاب را امتحان کنید و نتیجهٔ مورد انتظار را توضیح دهید.',
       '''
       def solve(data):
           query = data['query'].strip().casefold()
           matches = [title for title in data['titles'] if query and query in title.casefold()]
           return {'matches': matches}
       ''', [({'titles':['Python Basics','SQL','python Data'],'query':' PYTHON '},{'matches':['Python Basics','python Data']}), ({'titles':['کتاب پایتون'],'query':'جاوا'},{'matches':[]}), ({'titles':['A'],'query':' '},{'matches':[]})])

lesson('dictionary', 'دیکشنری در پایتون؛ کلید، مقدار و تجمیع', 'دفتر موجودی کالا',
       'تجمیع تعداد کالاهای تکراری با کلید رشته‌ای', 'dict · get · Aggregation',
       'دیکشنری مقدارها را با کلید نگه می‌دارد. به جای اینکه دنبال اندیس یک کالا بگردیم، نام کالا را کلید می‌کنیم. کلیدها یکتا هستند؛ مقداردهی دوبارهٔ یک کلید جای مقدار قبلی را می‌گیرد. برای موجودی باید مقدار تازه را به مقدار قبلی اضافه کنیم، نه اینکه هر سطر را روی سطر قبلی بنویسیم.',
       'هر عضو items شامل name و quantity است. برای هر سطر، تعداد قبلی را با get می‌خوانیم و مقدار جدید را جمع می‌کنیم. تعدادها در این تمرین صحیح و غیرمنفی‌اند. خروجی stock نگاشت نام کالا به مجموع تعداد است و total تعداد همهٔ واحدهای کالا را نشان می‌دهد؛ این با تعداد نوع کالا فرق دارد.',
       'نوشتن stock[name] += quantity برای اولین مشاهدهٔ کالا KeyError می‌دهد، چون کلید هنوز وجود ندارد. از get با مقدار پیش‌فرض صفر استفاده کنید. نام کالا دقیق مقایسه می‌شود؛ «دفتر» و «دفتر بزرگ» دو نوع مستقل‌اند و نباید با هم یکی شوند.',
       'یک کالا را در سه سطر پراکنده تکرار کنید. مجموع دستی را با برنامه مقایسه کنید و توضیح دهید چرا len(stock) با sum(stock.values()) معمولاً برابر نیست.',
       '''
       def solve(data):
           stock = {}
           for item in data['items']:
               name = item['name']
               stock[name] = stock.get(name, 0) + item['quantity']
           return {'stock': stock, 'total': sum(stock.values())}
       ''', [({'items':[{'name':'pen','quantity':2},{'name':'book','quantity':3},{'name':'pen','quantity':4}]},{'stock':{'pen':6,'book':3},'total':9}), ({'items':[]},{'stock':{},'total':0}), ({'items':[{'name':'دفتر','quantity':0}]},{'stock':{'دفتر':0},'total':0})])

lesson('functions', 'تابع در پایتون؛ ورودی، خروجی و مسئولیت مشخص', 'سبد خرید با تخفیف',
       'جداکردن محاسبهٔ جمع و اعمال تخفیف در تابع', 'def · Parameters · return',
       'تابع مجموعه‌ای از دستورها با نام مشخص است. ورودی را از پارامتر می‌گیرد و با return خروجی می‌دهد. تابع خوب یک مسئولیت روشن دارد؛ مثلاً جمع مبلغ سطرهای سبد خرید. جداکردن محاسبه از خواندن فایل کمک می‌کند همان منطق را با ورودی‌های مختلف آزمایش کنیم. تابع نباید برای محاسبه به متغیر سراسری پنهان وابسته باشد.',
       'تابع subtotal مجموع price ضرب در quantity همهٔ سطرها را می‌سازد. solve درصد تخفیف را بررسی می‌کند و مبلغ پس از تخفیف را برمی‌گرداند. تخفیف معتبر از صفر تا صد است. اگر ۱۰ درصد تخفیف داریم، باید مجموع را در ۰٫۹ ضرب کنیم؛ کم‌کردن عدد ۱۰ از مبلغ، همان معنی را ندارد.',
       'وقتی return فراموش شود، تابع None می‌دهد و ضرب بعدی روی آن خطا می‌سازد. نام متغیر total را به جای نام sum انتخاب کنید تا تابع داخلی sum را نپوشانید. گردکردن در پایان انجام می‌شود، نه بعد از هر ضرب کوچک.',
       'سبد خالی، تخفیف صفر و تخفیف صددرصد را آزمایش کنید. یک تابع دیگر برای تعداد کل واحدها بنویسید، بدون اینکه تابع محاسبهٔ قیمت را تغییر دهید.',
       '''
       def subtotal(items):
           return sum(item['price'] * item['quantity'] for item in items)

       def solve(data):
           discount = data['discount']
           if not 0 <= discount <= 100:
               return {'error': 'invalid_discount'}
           amount = subtotal(data['items'])
           return {'subtotal': round(amount, 2), 'total': round(amount * (1 - discount / 100), 2)}
       ''', [({'items':[{'price':20,'quantity':3}],'discount':10},{'subtotal':60,'total':54}), ({'items':[],'discount':0},{'subtotal':0,'total':0}), ({'items':[{'price':5,'quantity':2}],'discount':100},{'subtotal':10,'total':0}), ({'items':[],'discount':101},{'error':'invalid_discount'})])

lesson('boolean', 'منطق بولی و any؛ ساخت یک بررسی‌گر آموزشی', 'بررسی قواعد رشتهٔ آزمایشی',
       'ترکیب شرط‌ها و گزارش جداگانهٔ هر قاعده', 'bool · any · all · Methods',
       'مقدار بولی فقط دو حالت درست و نادرست دارد. all زمانی درست است که همهٔ شرط‌ها برقرار باشند و any با برقرارشدن دست‌کم یک شرط درست می‌شود. این الگو برای کنترل فرم‌ها و قواعد متن مفید است. در این تمرین یک رشتهٔ ساختگی را از نظر طول، حرف بزرگ، حرف کوچک و رقم بررسی می‌کنیم؛ هیچ رمز واقعی وارد نکنید.',
       'چهار قاعده را در دیکشنری checks نگه می‌داریم. برای وجود رقم، روی نویسه‌ها پیمایش می‌کنیم و نتیجهٔ isdigit را به any می‌دهیم. سپس all روی مقدارهای checks نتیجهٔ کلی را می‌سازد. نگه‌داشتن نتیجهٔ تک‌تک قواعد نشان می‌دهد کدام شرط شکست خورده، در حالی که یک جواب بله یا خیر چنین توضیحی ندارد.',
       'این فقط تمرین منطق است و سنجش امنیت رمز عبور نیست. طول هشت نویسه یا داشتن حرف بزرگ، امنیت واقعی را تضمین نمی‌کند. در محصول واقعی به ذخیره‌سازی امن، محدودیت تلاش و بررسی رمزهای رایج هم نیاز است؛ متن ورودی را نباید در گزارش‌ها ذخیره کرد.',
       'برای رشته‌های ساختگی Abcdef12 و abc و ABCD1234 نتیجهٔ هر قاعده را جدا پیش‌بینی کنید. بررسی کنید isdigit بعضی رقم‌های غیراَسکی را هم رقم می‌شناسد.',
       '''
       def solve(data):
           text = data['text']
           checks = {'length': len(text) >= 8, 'upper': any(c.isupper() for c in text), 'lower': any(c.islower() for c in text), 'digit': any(c.isdigit() for c in text)}
           return {'checks': checks, 'valid': all(checks.values())}
       ''', [({'text':'Abcdef12'},{'checks':{'length':True,'upper':True,'lower':True,'digit':True},'valid':True}), ({'text':'abc'},{'checks':{'length':False,'upper':False,'lower':True,'digit':False},'valid':False}), ({'text':''},{'checks':{'length':False,'upper':False,'lower':False,'digit':False},'valid':False})])

lesson('sets', 'مجموعه و حذف تکرار؛ حفظ ترتیب داده‌ها', 'فهرست یکتای شرکت‌کنندگان',
       'استفاده از set برای تشخیص تکرار و list برای حفظ ترتیب', 'set · Membership · Order',
       'مجموعه یا set عضوهای یکتا نگه می‌دارد و برای تشخیص اینکه چیزی قبلاً دیده شده مناسب است. اما ترتیب پیمایش set را نباید قرارداد خروجی در نظر گرفت. اگر می‌خواهیم فهرست یکتا با ترتیب اولین مشاهده داشته باشیم، از دو ساختار استفاده می‌کنیم: مجموعه برای بررسی تکرار و لیست برای ترتیب نمایش.',
       'برای هر نام، ابتدا آن را در seen جست‌وجو می‌کنیم. اگر قبلاً دیده نشده باشد، هم به seen و هم به unique اضافه می‌شود. نام تکراری فقط از خروجی یکتا حذف می‌شود و تعداد تکرارها در removed گزارش می‌شود. ورودی شامل رشته‌هاست؛ مقایسه دقیق است و حروف کوچک و بزرگ خودبه‌خود یکی نمی‌شوند.',
       'تبدیل مستقیم list(set(names)) ترتیب اولین مشاهده را تضمین نمی‌کند. همچنین set نمی‌تواند دیکشنری یا لیست را مستقیم عضو بگیرد، چون این نوع‌ها هش‌پذیر نیستند. قرارداد فعلی رشته‌ای است؛ برای دادهٔ پیچیده باید کلید یکتای مشخصی تعریف شود.',
       'ورودی [سارا، علی، سارا، رضا، علی] را دنبال کنید. سپس تصمیم بگیرید آیا نام با فاصلهٔ اضافی باید همان نام قبلی حساب شود؛ تغییر این تصمیم نیازمند تغییر قرارداد است.',
       '''
       def solve(data):
           seen, unique = set(), []
           for name in data['names']:
               if name not in seen:
                   seen.add(name)
                   unique.append(name)
           return {'unique': unique, 'removed': len(data['names']) - len(unique)}
       ''', [({'names':['سارا','علی','سارا','رضا','علی']},{'unique':['سارا','علی','رضا'],'removed':2}), ({'names':[]},{'unique':[],'removed':0}), ({'names':['A','a','A']},{'unique':['A','a'],'removed':1})])

lesson('reports', 'شکستن مسئله به تابع‌ها؛ گزارش نمرات', 'کارنامهٔ خلاصهٔ کلاس',
       'ترکیب اعتبارسنجی، شمارش و میانگین در یک گزارش', 'Functions · Validation · Lists',
       'یک مسئلهٔ چندمرحله‌ای را ابتدا روی کاغذ به بخش‌ها تقسیم کنید: دریافت داده، تشخیص نامعتبرها، محاسبه و ساخت خروجی. نوشتن همهٔ این کارها در یک عبارت طولانی خطایابی را سخت می‌کند. در کارنامهٔ کلاس، دامنهٔ نمره و حد قبولی دو قانون جدا هستند؛ یکی سلامت داده را می‌سنجد و دیگری نتیجهٔ آموزشی را تعیین می‌کند.',
       'اگر فهرست نمره‌ها خالی باشد، error=empty_grades می‌دهیم. هر نمره باید در بازهٔ صفر تا بیست باشد؛ وجود یک نمرهٔ نامعتبر کل گزارش را invalid_grade می‌کند. بعد از این بررسی‌ها، تابع passed_count نمره‌های حداقل ده را می‌شمارد. تعداد مردودها برابر تعداد کل منهای قبول‌هاست و میانگین از همهٔ نمرات معتبر محاسبه می‌شود.',
       'حذف پنهانی نمرهٔ نامعتبر، میانگین را بی‌اطلاع کاربر تغییر می‌دهد. برای همین این پروژه به جای نادیده‌گرفتن، خطای روشن برمی‌گرداند. تابعی که شمارش می‌کند بهتر است فقط عدد بدهد، نه اینکه هم‌زمان پیام چاپ کند و فایل بنویسد.',
       'نمرهٔ دقیق ده، کلاس تک‌نفره و فهرستی با یک عدد بیشتر از بیست را آزمایش کنید. برای هر حالت مشخص کنید کدام مرحله باید زودتر برنامه را متوقف کند.',
       '''
       def passed_count(grades):
           return sum(grade >= 10 for grade in grades)

       def solve(data):
           grades = data['grades']
           if not grades:
               return {'error': 'empty_grades'}
           if any(not 0 <= grade <= 20 for grade in grades):
               return {'error': 'invalid_grade'}
           passed = passed_count(grades)
           return {'mean': sum(grades) / len(grades), 'passed': passed, 'failed': len(grades) - passed}
       ''', [({'grades':[8,10,18]},{'mean':12,'passed':2,'failed':1}), ({'grades':[]},{'error':'empty_grades'}), ({'grades':[21]},{'error':'invalid_grade'}), ({'grades':[0]},{'mean':0,'passed':0,'failed':1})])

lesson('unicode', 'یونیکد و translate؛ عادی‌سازی رقم‌های فارسی', 'پاک‌ساز شناسهٔ عددی ساختگی',
       'تبدیل رقم فارسی و عربی به انگلیسی بدون تغییر طول', 'Unicode · translate · maketrans',
       'ظاهر شبیه دو نویسه لزوماً به معنی یکسان‌بودن آن‌ها نیست. رقم فارسی ۱، رقم عربی ١ و رقم انگلیسی 1 سه نویسهٔ متفاوت‌اند. وقتی یک سامانه شناسه‌ای فقط با رقم انگلیسی می‌خواهد، باید تبدیل مشخصی تعریف کنیم. در این تمرین شناسه‌ها کاملاً ساختگی هستند؛ از شماره و اطلاعات شخصی واقعی استفاده نکنید.',
       'با str.maketrans نگاشت ده رقم فارسی و ده رقم عربی به رقم انگلیسی می‌سازیم. translate این نگاشت را روی همهٔ متن اعمال می‌کند. فقط فاصله و خط تیره حذف می‌شوند؛ سایر نویسه‌ها مجاز نیستند. نتیجه باید دقیقاً شش رقم انگلیسی باشد. خروجی رشته می‌ماند تا صفرهای آغازین از بین نروند.',
       'تبدیل به int صفر ابتدای شناسه را حذف می‌کند. همچنین isdigit به تنهایی دامنه‌ای بزرگ‌تر از ۰ تا ۹ انگلیسی را قبول می‌کند؛ پس بعد از تبدیل، عضویت نویسه‌ها در رشتهٔ 0123456789 را بررسی می‌کنیم. عادی‌سازی بیش از حد ممکن است دادهٔ نادرست را معتبر جلوه دهد.',
       'شناسهٔ ساختگی ۰۰۱-۲۳۴ را با نسخهٔ عربی همان رقم‌ها مقایسه کنید. سپس یک حرف به وسط ورودی اضافه کنید و مطمئن شوید برنامه به‌جای حذف حرف، خطا می‌دهد.',
       '''
       def solve(data):
           table = str.maketrans('۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩', '01234567890123456789')
           value = data['value'].translate(table).replace(' ', '').replace('-', '')
           if len(value) != 6 or any(c not in '0123456789' for c in value):
               return {'error': 'invalid_id'}
           return {'normalized': value}
       ''', [({'value':'۰۰۱-۲۳۴'},{'normalized':'001234'}), ({'value':' ١٢٣ ٤٥٦ '},{'normalized':'123456'}), ({'value':'12A456'},{'error':'invalid_id'}), ({'value':''},{'error':'invalid_id'})])

lesson('csv', 'کتابخانهٔ استاندارد csv؛ خواندن جدول بدون نصب بسته', 'گزارش فروش از متن CSV',
       'خواندن جدول با DictReader و تبدیل صریح عددها', 'csv · io · DictReader',
       'کتابخانهٔ استاندارد همراه خود پایتون نصب می‌شود و برای بسیاری از کارهای روزمره کافی است. ماژول csv قواعد جداکننده، کوتیشن و سطرها را مدیریت می‌کند. استفاده از split(",") برای CSV واقعی قابل اعتماد نیست؛ ممکن است نام یک کالا خودش ویرگول داشته باشد. DictReader ستون‌ها را با نامشان در اختیار ما قرار می‌دهد.',
       'متن csv ورودی را با io.StringIO به شیئی شبیه فایل تبدیل می‌کنیم؛ بنابراین به فایل بیرونی نیاز نداریم. ستون‌های product، quantity و price الزامی‌اند و داده‌های این تمرین معتبرند. مقدار سلول‌ها رشته است، پس تعداد و قیمت را به عدد تبدیل می‌کنیم. فروش هر سطر quantity ضرب در price و فروش هر محصول مجموع سطرهای همان نام است.',
       'داشتن عنوان ستون بدون هیچ سطر داده خطا نیست؛ گزارش باید جمع صفر و نگاشت خالی بدهد. مقدار عددی ذخیره‌شده در CSV همچنان رشته است. اگر تبدیل را فراموش کنید، ضرب رشته در عدد صحیح متن را تکرار می‌کند و نتیجهٔ مالی نمی‌سازد.',
       'یک محصول تکراری و محصولی با تعداد صفر اضافه کنید. سپس نام یک محصول را داخل کوتیشن و دارای ویرگول بنویسید تا تفاوت parser استاندارد با split دستی را ببینید.',
       '''
       import csv
       import io

       def solve(data):
           totals = {}
           for row in csv.DictReader(io.StringIO(data['csv'])):
               amount = int(row['quantity']) * float(row['price'])
               totals[row['product']] = totals.get(row['product'], 0) + amount
           return {'total': round(sum(totals.values()), 2), 'by_product': {k: round(v, 2) for k, v in totals.items()}}
       ''', [({'csv':'product,quantity,price\nbook,2,10\npen,3,2\nbook,1,5\n'},{'total':31,'by_product':{'book':25,'pen':6}}), ({'csv':'product,quantity,price\n'},{'total':0,'by_product':{}}), ({'csv':'product,quantity,price\n"book, large",0,9\n'},{'total':0,'by_product':{'book, large':0}})], source='https://docs.python.org/3/library/csv.html')

lesson('json', 'JSON و تنظیمات؛ تفاوت متن و ساختار داده', 'بارگذاری تنظیمات برنامه',
       'تبدیل JSON به دیکشنری و ادغام با مقدارهای پیش‌فرض', 'json · loads · update',
       'JSON قالب متنی تبادل داده است، نه کد پایتون. دیکشنری در حافظه یک شیء است ولی متن JSON رشته است. json.loads متن را به ساختار داده تبدیل و json.dumps مسیر عکس را طی می‌کند. در JSON کلیدها کوتیشن دوتایی دارند و null و true با None و True پایتون فرق دارند.',
       'تنظیمات پیش‌فرض شامل theme برابر light و page_size برابر ده است. متن settings را می‌خوانیم و فقط کلیدهای شناخته‌شده را اعمال می‌کنیم. اگر theme داده نشده باشد همان مقدار پیش‌فرض می‌ماند. دادهٔ سطح اول باید یک شیء JSON باشد؛ لیست یا عدد قرارداد را برآورده نمی‌کند. مقدارهای کلیدهای شناخته‌شده در این تمرین از نوع معتبر ارسال می‌شوند.',
       'هرگز JSON را با eval نخوانید؛ eval کد اجرا می‌کند، در حالی که parser فقط داده می‌خواند. خطای JSONDecodeError را از خطای نوع ساختار جدا گزارش می‌کنیم. ادغام بدون محدودیت همهٔ کلیدها هم ممکن است تنظیمات ناشناخته را وارد برنامه کند.',
       'فقط theme را تغییر دهید و ببینید page_size حفظ می‌شود. سپس متن خراب، لیست JSON و کلید اضافی بفرستید و برای هر کدام نتیجهٔ مورد انتظار را مشخص کنید.',
       '''
       import json

       def solve(data):
           try:
               settings = json.loads(data['settings'])
           except json.JSONDecodeError:
               return {'error': 'invalid_json'}
           if not isinstance(settings, dict):
               return {'error': 'invalid_settings'}
           result = {'theme': 'light', 'page_size': 10}
           result.update({k: v for k, v in settings.items() if k in result})
           return result
       ''', [({'settings':'{"theme":"dark","extra":1}'},{'theme':'dark','page_size':10}), ({'settings':'{}'},{'theme':'light','page_size':10}), ({'settings':'{'},{'error':'invalid_json'}), ({'settings':'[]'},{'error':'invalid_settings'})], source='https://docs.python.org/3/library/json.html')

lesson('paths', 'pathlib و نام فایل؛ مسیر را مثل داده پردازش کنید', 'فهرست‌ساز پسوند فایل‌ها',
       'شناخت stem و suffix بدون دسترسی به دیسک', 'pathlib · PurePosixPath · suffix',
       'مسیر فایل را نباید با بریدن دستی رشته در محل نقطه یا اسلش تفسیر کرد. pathlib ابزار استاندارد پایتون برای کار با مسیرهاست. Path برای کار واقعی با فایل‌سیستم و PurePosixPath برای پردازش نحوی مسیرهای سبک لینوکس استفاده می‌شود. تمرین حاضر فقط نام‌ها را بررسی می‌کند و هیچ فایلی باز، حذف یا جابه‌جا نمی‌کند.',
       'برای هر نام ورودی، یک PurePosixPath می‌سازیم و suffix را می‌خوانیم. پسوند را به حروف کوچک تبدیل می‌کنیم تا .TXT و .txt در یک گروه باشند. فایل بدون پسوند در گروه [none] قرار می‌گیرد. در archive.tar.gz پسوند نهایی .gz است، نه .tar.gz؛ برای همهٔ پسوندها ابزار suffixes وجود دارد، ولی قرارداد این پروژه فقط آخرین پسوند را می‌خواهد.',
       'ساختن یک شیء مسیر به معنی امن‌بودن آن برای خواندن روی سرور نیست. مسیر دریافتی از کاربر برای دسترسی واقعی به دیسک به محدودیت پوشه و بررسی جدا نیاز دارد. اینجا عمداً فقط متن مسیر را تحلیل می‌کنیم تا هیچ دسترسی بیرونی لازم نباشد.',
       'نام report.CSV، archive.tar.gz، README و فایل مخفی .env.example را از نظر آخرین پسوند مقایسه کنید. برای تمرین فقط نام ساختگی بنویسید و محتوای فایل حساس را نخوانید.',
       '''
       from pathlib import PurePosixPath

       def solve(data):
           counts = {}
           for name in data['names']:
               suffix = PurePosixPath(name).suffix.lower() or '[none]'
               counts[suffix] = counts.get(suffix, 0) + 1
           return {'extensions': counts}
       ''', [({'names':['a.TXT','b.txt','archive.tar.gz','README']},{'extensions':{'.txt':2,'.gz':1,'[none]':1}}), ({'names':[]},{'extensions':{}}), ({'names':['dir/report.csv','photo.PNG']},{'extensions':{'.csv':1,'.png':1}})], source='https://docs.python.org/3/library/pathlib.html')

lesson('exceptions', 'خطایابی در پایتون؛ try و except هدفمند', 'مبدل امن متن به عدد صحیح',
       'گزارش ورودی‌های نامعتبر بدون پنهان‌کردن خطاهای برنامه', 'try · except · ValueError',
       'خطای نحوی مانع شروع برنامه می‌شود، ولی استثنا هنگام اجرای یک دستور رخ می‌دهد. تبدیل int("hello") نمونهٔ ValueError است؛ متن از نوع رشته است اما محتوای مناسب ندارد. پیام traceback را از خط آخر بخوانید و سپس به شمارهٔ خط خودتان برگردید. حذف پیام خطا راه حل نیست؛ باید علت و مرز قابل انتظار آن را پیدا کنید.',
       'برای هر رشتهٔ values، تلاش می‌کنیم آن را با int به عدد صحیح تبدیل کنیم. رشتهٔ دارای فاصلهٔ دو طرف و علامت منفی قابل قبول است؛ "2.5" عدد صحیح نیست. مقدارهای موفق در numbers می‌آیند و اندیس مقدارهای ناموفق در invalid_indices ذخیره می‌شود. ترتیب هر دو فهرست باید با ورودی سازگار باشد.',
       'except بدون مشخص‌کردن نوع، خطاهای برنامه‌نویسی مثل نام متغیر اشتباه را هم پنهان می‌کند. فقط ValueError قابل انتظار از تبدیل را بگیرید. ورودی این تمرین همیشه لیست رشته‌هاست؛ اضافه‌کردن مدیریت ده‌ها نوع فرضی، هدف آموزش را گم می‌کند.',
       'ورودی‌های " 12 "، "-3"، "2.5" و رشتهٔ خالی را امتحان کنید. بعد عمداً نام یک متغیر را اشتباه بنویسید و بررسی کنید چرا آن خطا نباید به عنوان ورودی نامعتبر گزارش شود.',
       '''
       def solve(data):
           numbers, invalid = [], []
           for index, text in enumerate(data['values']):
               try:
                   numbers.append(int(text))
               except ValueError:
                   invalid.append(index)
           return {'numbers': numbers, 'invalid_indices': invalid}
       ''', [({'values':[' 12 ','bad','-3','2.5']},{'numbers':[12,-3],'invalid_indices':[1,3]}), ({'values':[]},{'numbers':[],'invalid_indices':[]}), ({'values':['0','+7','']},{'numbers':[0,7],'invalid_indices':[2]})], source='https://docs.python.org/3/tutorial/errors.html')

lesson('dates', 'تاریخ در پایتون؛ محاسبهٔ فاصلهٔ روزها', 'شمارندهٔ روز تا موعد',
       'پردازش تاریخ ISO با کتابخانهٔ استاندارد datetime', 'datetime · date · timedelta',
       'تاریخ را نباید مثل عدد سال‌ماه‌روز از هم کم کرد؛ طول ماه‌ها و سال کبیسه این روش را خراب می‌کند. ماژول datetime تقویم میلادی را می‌شناسد و اختلاف دو date را به timedelta تبدیل می‌کند. در این تمرین تاریخ‌ها میلادی و بدون ساعت هستند. این قرارداد را با تاریخ جلالی یا منطقهٔ زمانی اشتباه نگیرید.',
       'fromisoformat تاریخ با شکل YYYY-MM-DD را می‌خواند. تاریخ due را از today کم می‌کنیم و days را از نتیجه می‌گیریم. مقدار مثبت یعنی موعد در آینده است، صفر یعنی امروز و مقدار منفی یعنی موعد گذشته. overdue فقط وقتی درست است که فاصله منفی باشد. عبور از مرز ماه یا سال به‌صورت خودکار محاسبه می‌شود.',
       'نوشتن تاریخ ناممکن مثل روز سی‌ام فوریه ValueError می‌دهد. آن را به invalid_date تبدیل می‌کنیم؛ حدس‌زدن یک روز جایگزین مناسب نیست. برای برنامه‌های دارای ساعت، آگاهی از timezone لازم است، ولی افزودن زمان محلی دستگاه به این تمرین نتیجه را غیرقابل تکرار می‌کند.',
       'فاصلهٔ ۲۸ فوریه تا اول مارس در سال ۲۰۲۴ و سال ۲۰۲۵ را مقایسه کنید. ورودی today همیشه داده می‌شود تا نتیجه به روز اجرای آزمون وابسته نباشد.',
       '''
       from datetime import date

       def solve(data):
           try:
               today = date.fromisoformat(data['today'])
               due = date.fromisoformat(data['due'])
           except ValueError:
               return {'error': 'invalid_date'}
           days = (due - today).days
           return {'days': days, 'overdue': days < 0}
       ''', [({'today':'2024-02-28','due':'2024-03-01'},{'days':2,'overdue':False}), ({'today':'2026-01-02','due':'2026-01-01'},{'days':-1,'overdue':True}), ({'today':'2026-01-01','due':'2026-01-01'},{'days':0,'overdue':False}), ({'today':'2026-02-30','due':'2026-03-01'},{'error':'invalid_date'})], source='https://docs.python.org/3/library/datetime.html')

lesson('statistics', 'ماژول statistics؛ میانگین و میانه چه فرقی دارند؟', 'گزارش مقاوم زمان مطالعه',
       'مقایسهٔ mean و median روی دادهٔ دارای مقدار بزرگ', 'statistics · mean · median',
       'کتابخانهٔ استاندارد statistics برای محاسبات آماری ساده کافی است و نیازی به نصب NumPy ندارد. میانگین از همهٔ مقدارها تأثیر می‌گیرد، در حالی که میانه مقدار وسطِ دادهٔ مرتب‌شده است. در دادهٔ با تعداد زوج، میانه میانگین دو عضو وسط است. یک عدد بسیار بزرگ می‌تواند میانگین را به‌وضوح تغییر دهد ولی اثرش بر میانه کمتر باشد.',
       'در این پروژه زمان مطالعهٔ چند جلسه در minutes می‌آید. با mean میانگین و با median میانه را می‌گیریم و spread را از بیشینه منهای کمینه حساب می‌کنیم. دادهٔ خالی شاخص قابل محاسبه ندارد و error=empty_data برمی‌گرداند. در دادهٔ تک‌عضوی، هر دو شاخص همان مقدار و دامنه صفر است.',
       'میانه به معنی عدد پرت‌نداشتن داده نیست و نباید بدون توضیح جای همهٔ شاخص‌ها بنشیند. همچنین میانگین گروه‌ها را نمی‌توان همیشه با میانگین سادهٔ میانگین‌هایشان ترکیب کرد؛ تعداد مشاهده‌های هر گروه مهم است. این تمرین روی دادهٔ خام همان فهرست محاسبه می‌کند.',
       'فهرست [۱۰، ۲۰، ۳۰] و سپس [۱۰، ۲۰، ۳۰۰] را مقایسه کنید. قبل از اجرا بنویسید کدام شاخص بیشتر تغییر می‌کند و چه چیزی دربارهٔ الگوی مطالعه می‌گوید.',
       '''
       from statistics import mean, median

       def solve(data):
           values = data['minutes']
           if not values:
               return {'error': 'empty_data'}
           return {'mean': mean(values), 'median': median(values), 'spread': max(values) - min(values)}
       ''', [({'minutes':[10,20,300]},{'mean':110,'median':20,'spread':290}), ({'minutes':[2,4,6,8]},{'mean':5,'median':5,'spread':6}), ({'minutes':[]},{'error':'empty_data'}), ({'minutes':[7]},{'mean':7,'median':7,'spread':0})], source='https://docs.python.org/3/library/statistics.html')

lesson('decimal', 'Decimal و دقت مالی؛ گردکردن را صریح تعریف کنید', 'فاکتور دقیق با اعشار ده‌دهی',
       'محاسبهٔ مبلغ با Decimal و قالب خروجی دو رقم اعشار', 'decimal · Quantize · Rounding',
       'float برای محاسبات عمومی مفید است ولی همهٔ کسرهای ده‌دهی را دقیق نمایش نمی‌دهد. ماژول decimal عدد ده‌دهی را با قواعد دقت و گردکردن مشخص محاسبه می‌کند. برای حفظ مقدار اولیه، Decimal را از رشته می‌سازیم، نه از float. این تمرین قیمت‌ها را رشتهٔ ده‌دهی می‌گیرد و تعدادها عدد صحیح غیرمنفی‌اند.',
       'هر قیمت رشته‌ای با Decimal خوانده و در quantity ضرب می‌شود. جمع از Decimal("0") آغاز می‌شود تا همهٔ محاسبه‌ها ده‌دهی بمانند. در پایان quantize با 0.01 و ROUND_HALF_UP اعمال می‌شود؛ یعنی نیم‌صدم رو به بالا گرد می‌شود. خروجی total عمداً رشته است تا همیشه دو رقم اعشار، حتی برای صفر، حفظ شود.',
       'Decimal(0.1) ابتدا تقریب float را دریافت می‌کند و دیگر نمایش دقیق ورودی ده‌دهی نیست. Decimal("0.1") را انتخاب کنید. گردکردن هر سطر و گردکردن فقط جمع نهایی ممکن است دو نتیجهٔ متفاوت بدهند؛ قرارداد این پروژه فقط جمع نهایی را گرد می‌کند.',
       'سه واحد با قیمت "0.10" و یک واحد با قیمت "0.105" را جدا بررسی کنید. نتیجهٔ جمع خالی هم باید "0.00" باشد، نه عدد صفر یا رشتهٔ بدون اعشار.',
       '''
       from decimal import Decimal, ROUND_HALF_UP

       def solve(data):
           total = sum((Decimal(item['price']) * item['quantity'] for item in data['items']), Decimal('0'))
           return {'total': str(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))}
       ''', [({'items':[{'price':'0.10','quantity':3}]},{'total':'0.30'}), ({'items':[{'price':'0.105','quantity':1}]},{'total':'0.11'}), ({'items':[]},{'total':'0.00'})], source='https://docs.python.org/3/library/decimal.html')

lesson('testing', 'تست تابع در پایتون؛ assert و مثال نقض', 'تشخیص عدد اول با آزمون مرزی',
       'ساخت تابع مستقل و بررسی ورودی‌های مرزی', 'Testing · assert · Functions',
       'تست یعنی مقایسهٔ رفتار برنامه با انتظار از پیش تعیین‌شده. تستی که فقط اجراشدن را بسنجد، درست‌بودن جواب را تضمین نمی‌کند. برای تابع تشخیص عدد اول، دانستن نتیجهٔ چند عدد آسان کمک می‌کند خطای منطقی را سریع پیدا کنیم. عدد اول صحیحی بزرگ‌تر از یک است که جز یک و خودش مقسوم‌علیه مثبت دیگری ندارد.',
       'تابع is_prime ابتدا عددهای کمتر از دو را رد می‌کند. سپس مقسوم‌علیه‌ها را تا وقتی مربعشان از n بیشتر نشده بررسی می‌کند؛ اگر هیچ مقسوم‌علیهی پیدا نشود عدد اول است. solve نتیجهٔ تابع را برای همهٔ عددهای ورودی به ترتیب می‌سازد. برای تمرین محلی می‌توانید assert is_prime(2) و assert not is_prime(1) را اضافه کنید.',
       'عدد یک اول نیست و فراموش‌کردن این شرط خطای رایج است. شرط حلقه باید <= باشد تا مربع عدد اول مانند ۴۹ اشتباه پذیرفته نشود. assert ابزار مناسب تست و تمرین است، نه اعتبارسنجی امنیتی ورودی در محصول؛ اجرای بهینهٔ پایتون ممکن است assert را حذف کند.',
       'تست برای منفی۷، صفر، یک، دو، نه و چهل‌ونه بنویسید. سپس عمداً <= را به < تبدیل کنید و ببینید کدام تست خطای تازه را آشکار می‌کند.',
       '''
       def is_prime(n):
           if n < 2:
               return False
           divisor = 2
           while divisor * divisor <= n:
               if n % divisor == 0:
                   return False
               divisor += 1
           return True

       def solve(data):
           return {'prime': [is_prime(n) for n in data['numbers']]}
       ''', [({'numbers':[-7,0,1,2,3,9,49]},{'prime':[False,False,False,True,True,False,False]}), ({'numbers':[17,25,97]},{'prime':[True,False,True]}), ({'numbers':[]},{'prime':[]})], source='https://docs.python.org/3/library/unittest.html')

lesson('numpy', 'محیط مجازی، pip و شروع NumPy از صفر', 'گزارش عددی با آرایهٔ NumPy',
       'ساخت آرایه، محاسبهٔ برداری و تبدیل خروجی به نوع JSON', 'venv · pip · NumPy · ndarray',
       'NumPy کتابخانه‌ای خارجی برای محاسبات عددی است و همراه خود پایتون نصب نمی‌شود. در رایانهٔ شخصی ابتدا python -m venv .venv را اجرا کنید؛ در لینوکس و مک با source .venv/bin/activate و در PowerShell با .\\.venv\\Scripts\\Activate.ps1 محیط را فعال کنید. سپس python -m pip install numpy را در همان محیط اجرا کنید. در میزکار سایت کتابخانه از قبل آماده است و نصب آنلاین از ترمینال مجاز نیست.',
       'با np.asarray و dtype=float، فهرست عددها به آرایه تبدیل می‌شود. mean و max خلاصه‌های عددی را می‌دهند و تفریق میانگین از کل آرایه یک محاسبهٔ برداری است. خروجی centered نشان می‌دهد هر عدد چقدر از میانگین فاصله دارد؛ جمع این فاصله‌ها تقریباً صفر است. این کار فقط مرکزکردن است و با استانداردسازی بر اساس انحراف معیار فرق دارد.',
       'عدد و آرایهٔ NumPy همیشه مستقیماً با json.dumps سازگار نیستند. float مقدار اسکالر و tolist آرایه را به نوع‌های عادی پایتون تبدیل می‌کند. برای ورودی خالی، قبل از mean خطای empty_data می‌دهیم تا هشدار و مقدار NaN تولید نشود. در پروژه‌های شخصی نسخهٔ وابستگی‌ها را در requirements.txt ثبت کنید.',
       'آرایهٔ [۲، ۴، ۶] را مرکز کنید و خروجی را دستی بسنجید. اگر ModuleNotFoundError دیدید، python -m pip --version و مسیر مفسر فعال را بررسی کنید؛ نصب تصادفی در محیط دیگر مشکل را حل نمی‌کند.',
       '''
       import numpy as np

       def solve(data):
           values = np.asarray(data['values'], dtype=float)
           if values.size == 0:
               return {'error': 'empty_data'}
           average = float(values.mean())
           return {'mean': average, 'max': float(values.max()), 'centered': (values - average).tolist()}
       ''', [({'values':[2,4,6]},{'mean':4,'max':6,'centered':[-2,0,2]}), ({'values':[5]},{'mean':5,'max':5,'centered':[0]}), ({'values':[]},{'error':'empty_data'})], ['numpy'], 'https://numpy.org/doc/stable/user/absolute_beginners.html')

lesson('pandas', 'شروع Pandas؛ از دیکشنری تا DataFrame و groupby', 'گزارش دسته‌های هزینه با Pandas',
       'ساخت جدول و تجمیع مبلغ بر اساس دسته', 'Pandas · DataFrame · groupby',
       'Pandas دادهٔ جدولی را با DataFrame نمایش می‌دهد. هر ستون نام و نوع دارد و هر سطر یک مشاهده است. برای شروع کافی است لیستی از دیکشنری‌های هم‌شکل داشته باشید؛ لازم نیست فایل بزرگ یا پایگاه داده بسازید. در محیط مجازی رایانهٔ شخصی python -m pip install pandas را اجرا کنید؛ در میزکار سایت این کتابخانه آماده است.',
       'از rows یک DataFrame با ستون‌های category و amount می‌سازیم. groupby بر اساس دسته، سطرهای هم‌نام را کنار هم قرار می‌دهد و sum مبلغ هر گروه را جمع می‌کند. نتیجه ابتدا Series است و با to_dict به نگاشت قابل استفاده در JSON تبدیل می‌شود. مجموع کل از همان ستون amount به دست می‌آید؛ مقدارها در این قرارداد عددی و غیرگمشده‌اند.',
       'groupby به‌تنهایی جمع نمی‌زند؛ باید ستون و عمل تجمیع را مشخص کنید. نام ستون اشتباه KeyError می‌دهد و باید با قرارداد ورودی مقایسه شود. دادهٔ خالی را پیش از ساخت گزارش مدیریت می‌کنیم. مقدار خالی و مقدار صفر یکی نیستند؛ این پروژه فقط صفر واقعی را می‌پذیرد و پاک‌سازی missing را به تمرین بعدی موکول می‌کند.',
       'دو هزینه در دستهٔ book و یک هزینه در دستهٔ transport اضافه کنید. مجموع گروه‌ها را با total مقایسه کنید. سپس یک سطر با مبلغ صفر بیفزایید و بررسی کنید دسته در گزارش باقی می‌ماند.',
       '''
       import pandas as pd

       def solve(data):
           if not data['rows']:
               return {'total': 0, 'by_category': {}}
           frame = pd.DataFrame(data['rows'], columns=['category', 'amount'])
           grouped = frame.groupby('category')['amount'].sum()
           return {'total': float(frame['amount'].sum()), 'by_category': {str(k): float(v) for k, v in grouped.items()}}
       ''', [({'rows':[{'category':'book','amount':10},{'category':'transport','amount':5},{'category':'book','amount':2}]},{'total':17,'by_category':{'book':12,'transport':5}}), ({'rows':[]},{'total':0,'by_category':{}}), ({'rows':[{'category':'food','amount':0}]},{'total':0,'by_category':{'food':0}})], ['pandas'], 'https://pandas.pydata.org/docs/getting_started/intro_tutorials/index.html')


